using System;
using System.IO;
using System.Windows.Media.Imaging;

namespace HTHIUM.Views.Pages.Common
{
    internal static class LoginAssistantImageAssets
    {
        private static readonly Lazy<BitmapImage> IdleImage = new(() => CreateImage(IdlePngBase64));
        private static readonly Lazy<BitmapImage> CoverImage = new(() => CreateImage(CoverPngBase64));

        public static BitmapImage Idle => IdleImage.Value;
        public static BitmapImage Cover => CoverImage.Value;

        private static BitmapImage CreateImage(string base64)
        {
            var bytes = Convert.FromBase64String(base64);
            using var stream = new MemoryStream(bytes);
            var image = new BitmapImage();
            image.BeginInit();
            image.CacheOption = BitmapCacheOption.OnLoad;
            image.StreamSource = stream;
            image.EndInit();
            image.Freeze();
            return image;
        }

